// ServerInterface represents all server handlers.
type ServerInterface interface {
	// List Netscape cookie jars on host domain overrides
	// (GET /api/domains/cookies)
	ListDomainCookies(w http.ResponseWriter, r *http.Request)
	// List soft-paused hostname queue lanes
	// (GET /api/domains/paused)
	ListPausedDomains(w http.ResponseWriter, r *http.Request)
	// Set whether a domain is active (inactive domains do not run queue tasks; deactivating cancels pending and running tasks for that host)
	// (PUT /api/domains/{domain}/active)
	SetDomainActive(w http.ResponseWriter, r *http.Request, domain Domain)
	// Clear the Netscape jar on a host domain override
	// (DELETE /api/domains/{domain}/cookies)
	ClearDomainCookies(w http.ResponseWriter, r *http.Request, domain Domain)
	// Create or replace the Netscape jar on a host domain override
	// (PUT /api/domains/{domain}/cookies)
	SetDomainCookies(w http.ResponseWriter, r *http.Request, domain Domain)
	// Soft-pause or resume a domain queue lane (ClaimNext blocked; interactive metadata prefetch still runs; pending stay queued; running continue; does not create a domains override row)
	// (PUT /api/domains/{domain}/paused)
	SetDomainPaused(w http.ResponseWriter, r *http.Request, domain Domain)
	// Dependency health checks
	// (GET /api/health)
	GetHealth(w http.ResponseWriter, r *http.Request)
	// Finished tasks (History)
	// (GET /api/history)
	ListHistory(w http.ResponseWriter, r *http.Request, params ListHistoryParams)
	// Confirm bind or create unmatched video - enqueue import task
	// (POST /api/import/manual)
	ImportManual(w http.ResponseWriter, r *http.Request)
	// Series and video catalog for Import Match UI
	// (GET /api/import/picker)
	GetImportPicker(w http.ResponseWriter, r *http.Request)
	// Scan import inbox or one library root for untracked files
	// (POST /api/import/scan)
	ScanImport(w http.ResponseWriter, r *http.Request, params ScanImportParams)
	// In-app notification log
	// (GET /api/notifications)
	ListNotifications(w http.ResponseWriter, r *http.Request, params ListNotificationsParams)
	// Mark all unread alert notifications as read
	// (POST /api/notifications/read-all)
	MarkAllNotificationsRead(w http.ResponseWriter, r *http.Request)
	// Unread alert notification count
	// (GET /api/notifications/unread-count)
	GetNotificationUnreadCount(w http.ResponseWriter, r *http.Request)
	// One notification
	// (GET /api/notifications/{id})
	GetNotification(w http.ResponseWriter, r *http.Request, id TaskId)
	// Mark one notification as read
	// (POST /api/notifications/{id}/read)
	MarkNotificationRead(w http.ResponseWriter, r *http.Request, id TaskId)
	// List quality profiles
	// (GET /api/quality-profiles)
	ListQualityProfiles(w http.ResponseWriter, r *http.Request)
	// Create a quality profile
	// (POST /api/quality-profiles)
	CreateQualityProfile(w http.ResponseWriter, r *http.Request)
	// Delete a quality profile
	// (DELETE /api/quality-profiles/{id})
	DeleteQualityProfile(w http.ResponseWriter, r *http.Request, id QualityProfileId)
	// Update a quality profile
	// (PATCH /api/quality-profiles/{id})
	UpdateQualityProfile(w http.ResponseWriter, r *http.Request, id QualityProfileId)
	// List root folders
	// (GET /api/roots)
	ListRoots(w http.ResponseWriter, r *http.Request)
	// Create a root folder
	// (POST /api/roots)
	CreateRoot(w http.ResponseWriter, r *http.Request)
	// Delete a root folder
	// (DELETE /api/roots/{id})
	DeleteRoot(w http.ResponseWriter, r *http.Request, id RootId)
	// Update a root folder
	// (PATCH /api/roots/{id})
	UpdateRoot(w http.ResponseWriter, r *http.Request, id RootId)
	// List series with sources and counts
	// (GET /api/series)
	ListSeries(w http.ResponseWriter, r *http.Request)
	// Create a series (optional first source)
	// (POST /api/series)
	CreateSeries(w http.ResponseWriter, r *http.Request)
	// Enqueue delete_files for many series (removes library files on disk)
	// (POST /api/series/bulk-delete)
	BulkDeleteSeries(w http.ResponseWriter, r *http.Request)
	// Bulk-edit series root folder, quality profile, and/or delivery mode
	// (POST /api/series/bulk-edit)
	BulkEditSeries(w http.ResponseWriter, r *http.Request)
	// Bulk-override series catalog metadata fields
	// (POST /api/series/bulk-metadata)
	BulkEditSeriesMetadata(w http.ResponseWriter, r *http.Request)
	// Set monitored on many series
	// (POST /api/series/bulk-monitored)
	BulkSetSeriesMonitored(w http.ResponseWriter, r *http.Request)
	// List series ids matching the same filters as the series list UI
	// (GET /api/series/ids)
	ListSeriesIds(w http.ResponseWriter, r *http.Request, params ListSeriesIdsParams)
	// Delete a series and its sources/indexed entries (library files on disk are kept; UI delete always removes library files after confirm)
	// (DELETE /api/series/{id})
	DeleteSeries(w http.ResponseWriter, r *http.Request, id SeriesId)
	// Series detail with sources and videos
	// (GET /api/series/{id})
	GetSeries(w http.ResponseWriter, r *http.Request, id SeriesId)
	// Enqueue metadata rescan for existing videos (no discovery)
	// (POST /api/series/{id}/metadata-rescan)
	MetadataRescanSeries(w http.ResponseWriter, r *http.Request, id SeriesId)
	// Enqueue full scan for sources that still need indexing
	// (POST /api/series/{id}/scan)
	ScanSeries(w http.ResponseWriter, r *http.Request, id SeriesId)
	// Add a source URL to a series
	// (POST /api/series/{id}/sources)
	AddSource(w http.ResponseWriter, r *http.Request, id SeriesId)
	// Delete a source and all of its videos
	// (DELETE /api/series/{id}/sources/{sourceId})
	DeleteSource(w http.ResponseWriter, r *http.Request, id SeriesId, sourceId SourceId)
	// Update a source
	// (PATCH /api/series/{id}/sources/{sourceId})
	UpdateSource(w http.ResponseWriter, r *http.Request, id SeriesId, sourceId SourceId)
	// Create an indexed ignored video under a series
	// (POST /api/series/{id}/videos)
	CreateSeriesVideo(w http.ResponseWriter, r *http.Request, id SeriesId)
	// List video ids for a series matching the same filters as the video list UI
	// (GET /api/series/{id}/videos/ids)
	ListSeriesVideoIds(w http.ResponseWriter, r *http.Request, id SeriesId, params ListSeriesVideoIdsParams)
	// List editable settings with help text
	// (GET /api/settings)
	ListSettings(w http.ResponseWriter, r *http.Request)
	// Update one or more settings
	// (PUT /api/settings)
	UpdateSettings(w http.ResponseWriter, r *http.Request)
	// Running and pending tasks by domain queue
	// (GET /api/tasks)
	ListTasks(w http.ResponseWriter, r *http.Request)
	// Enqueue a task (manual / tests)
	// (POST /api/tasks)
	EnqueueTask(w http.ResponseWriter, r *http.Request)
	// Cancel all pending tasks
	// (POST /api/tasks/cancel-all)
	CancelAllTasks(w http.ResponseWriter, r *http.Request)
	// Cancel a pending or running task
	// (POST /api/tasks/{id}/cancel)
	CancelTask(w http.ResponseWriter, r *http.Request, id TaskId)
	// Enqueue delete_files for many downloaded/missing videos
	// (POST /api/videos/bulk-delete)
	BulkDeleteVideos(w http.ResponseWriter, r *http.Request)
	// Queue download for many videos (Queue download semantics)
	// (POST /api/videos/bulk-download)
	BulkDownloadVideos(w http.ResponseWriter, r *http.Request)
	// Ignore many videos (skips downloaded / integrity_check_failed)
	// (POST /api/videos/bulk-ignore)
	BulkIgnoreVideos(w http.ResponseWriter, r *http.Request)
	// Bulk-override video catalog metadata fields
	// (POST /api/videos/bulk-metadata)
	BulkEditVideosMetadata(w http.ResponseWriter, r *http.Request)
	// Queue sidecar refresh for videos that have packed media
	// (POST /api/videos/bulk-refresh-sidecars)
	BulkRefreshSidecarsVideos(w http.ResponseWriter, r *http.Request)
	// Set wanted on many videos (eligible statuses only)
	// (POST /api/videos/bulk-want)
	BulkWantVideos(w http.ResponseWriter, r *http.Request)
	// Get one indexed video
	// (GET /api/videos/{id})
	GetVideo(w http.ResponseWriter, r *http.Request, id VideoId)
	// Enqueue metadata rescan for one indexed video
	// (POST /api/videos/{id}/metadata-rescan)
	MetadataRescanVideo(w http.ResponseWriter, r *http.Request, id VideoId)
	// Set status to wanted from ignored, deleted, or missing; does not enqueue download
	// (POST /api/videos/{id}/want)
	WantVideo(w http.ResponseWriter, r *http.Request, id VideoId)
}

